import os as _lovophon_os
from pathlib import Path as _LovophonPath
_LOVOPHON_WORKSPACE = _lovophon_os.environ.get('LOVOPHON_WORKSPACE', str(_LovophonPath(__file__).resolve().parents[1]))
from pathlib import Path
import json,csv,collections
R=Path((_LOVOPHON_WORKSPACE + ''));O=R/'outputs';d=json.loads((O/'Lovophone_Hardware_Frame_Design.json').read_text())
c=collections.Counter((p['source_class'],p['specification']) for p in d['new_parts'])
with (O/'Lovophone_Hardware_Frame_Parts.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['Quantity','Source category','Item / nominal specification'])
 for (kind,spec),n in sorted(c.items()):w.writerow([n,kind,spec])
 w.writerow([1,'hardware-store sheet stock','6 mm plywood drive deck, 288 × 78 mm, four 4.4 mm mounting holes'])
 w.writerow([1,'smooth shaft stock','6 mm common input shaft, 314.25 mm modeled length; check bearing fit and deburr sawn ends'])
 w.writerow([1,'cut and thread smooth stock','6 mm stationary axle, 307.85 mm modeled length; M6 threads on about 9 mm left and 7 mm right ends only'])
lines=['# Le Lovophone — simple drive frame','','This revision changes the low drive support and mounting hardware. The approved pentatonic string pitches, bridge positions, arm lengths, cam/follower geometry and rhythmic ratios are unchanged. Existing pentatonic MIDI stays synchronized at 120 BPM, time zero.','','## Cut from ordinary stock','','| Part | Quantity | Stock and cut |','|---|---:|---|','| Identical end plates | 2 | 50 × 4 mm flat steel, cut 59 mm long |','| Identical angle feet | 4 | 20 × 20 × 2 mm equal angle, cut 15 mm long |','| Drive deck | 1 | 6 mm plywood, 288 × 78 mm |','| Input shaft | 1 | Smooth 6 mm rod; modeled length 314.25 mm |','| Stationary axle | 1 | Smooth 6 mm rod; modeled length 307.85 mm, M6-threaded ends only |','| Input collar spacer | 1 | 8 × 1 mm brass tube, cut 3 mm; deburr bore to fit the 6 mm shaft |','','Each end plate has six holes: a 12.1 mm clearance hole for the input bearing, a 6.5 mm stationary-axle hole, two 3.4 mm bearing-retainer holes, and two 4.4 mm foot holes. The two plates use the same drilling template. Each angle foot needs just one 4.4 mm hole in each leg. The plywood deck is a plain rectangle with four through holes. No machined bearing block, folded tray lip or proprietary frame connector is needed for the low drive.','','Use smooth, straight rod through bearing and pulley journals. Ordinary hardware-store rod may need a fit check; use precision 6 mm shaft stock if it is oversize, rough or bent. Do not substitute fully threaded M6 rod beneath the rotating pulley bushes. The stationary axle needs M6 threads cut only on its exposed ends, using a normal hand die; its middle stays smooth. The exposed threaded ends and nuts are modeled as nominal envelopes, not helical thread geometry.','','## Replaceable bought-in hardware','','The new drive frame uses two MR126-2RS or MR126ZZ bearings, 6 × 12 × 4 mm. The open MR126 version can be 3 mm wide: buy the stated sealed/shielded dimensions. Plain M3 washers and M3 × 10 bolts with nuts retain the bearing outer races. M4 × 12 bolts attach the end plates to the angle feet; M4 × 20 through-bolts attach feet and deck to the lid, with nuts accessible inside the soundbox. Two ordinary M6 nuts fix the stationary axle. A DIN 705-style 6 mm shaft collar and a short brass-tube spacer retain the rotating input shaft; check the actual collar and set-screw dimensions before buying.','','The motor stays a bought-in N20-type assembly. Its bracket, coupling, supplier mounting holes and electrical implementation are still provisional. The left gantry end frame is moved 6 mm outwards for spanner access; all musical pivots stay in place. The motor assembly moves 2.6 mm along the shaft for ordinary retaining-screw access. The coupling sleeve and small clear panels are trimmed to remain within the existing carry envelope.','','## What still needs a specialist supplier or fabrication','','This is a hardware-stock **drive-frame** revision, not a claim that every part of the instrument is on a general hardware-store shelf. Timing belts, correctly toothed ratio pulleys, bearings, motor and shaft collar are motion/hobby-supplier items. The ratio cams, pulley details, upper gantry bearing forks, tuning fittings and instrument bridges still include custom parts. The twelve pulley ratios are musical timing components: arbitrary hardware-shop pulleys are not equivalent. Belt tooth forms, stock belt-length selection, tension adjustment and supplier fits still need detailing before manufacture.','','## Reference sources','','- [50 × 4 mm steel flat stock in a hardware retailer catalogue](https://www.leroymerlin.fr/produits/fer-plat-acier-50mm-ep-4-mm-longueur-4-metres-88312800.html). This verifies a stock section, not local branch availability.','- [20 × 20 × 2 mm angle in a hardware retailer catalogue](https://www.leroymerlin.fr/produits/corniere-alu-20x20-longueur-2-metres-88311541.html). Supplier material and thickness must match the chosen build.','- [EZO manufacturer bearing specification](https://www.ezo-brg.co.jp/english/product/spec.php?eid=00605). Confirm the exact shielded/sealed bearing dimensions when ordering.','','## Checks and prototype limits','','The accompanying clearance report records sampled full-cycle checks of all twelve mechanisms and intersections involving the new frame hardware. It does not verify strength, fatigue, bearing fits, fastener preload, tube crushing, motor torque, electrical safety, actual string tuning, bridge downforce or plucking reliability. The drilling template is a development aid: print at 100% and verify its 50 mm calibration line, then compare against the selected hardware before drilling. The STEP/native model remains a prototype design, not released fabrication drawings.','','The original model and earlier videos are preserved. The new textured scene uses this revised CAD, procedural materials and five studio lights; cosmetic render bevels do not change the engineering model.']
(O/'Lovophone_Hardware_Frame_Notes.md').write_text('\n'.join(lines)+'\n')
# A true-size SVG with the identical flat end-plate hole pattern.
a=['<svg xmlns="http://www.w3.org/2000/svg" width="100mm" height="110mm" viewBox="0 0 100 110">','<rect width="100" height="110" fill="white"/>','<g font-family="Arial,sans-serif" fill="#222">','<text x="10" y="7" font-size="3.5">Lovophone drive end plate — make 2</text>','<text x="10" y="12" font-size="2.7">50 × 59 × 4 mm steel · development template</text>','<rect x="25" y="20" width="50" height="59" fill="none" stroke="black" stroke-width="0.25"/>']
def hole(y,z,dia,label):
 x=25+z+151;yy=20-44-y
 a.append(f'<circle cx="{x}" cy="{yy}" r="{dia/2}" fill="none" stroke="black" stroke-width="0.2"/>')
 a.append(f'<path d="M {x-1.2},{yy} h 2.4 M {x},{yy-1.2} v 2.4" fill="none" stroke="#666" stroke-width="0.12"/>')
 a.append(f'<text x="{x+dia/2+1}" y="{yy+.7}" font-size="2.2">{label}</text>')
hole(-83,-131,12.1,'Ø12.1');hole(-59,-116,6.5,'Ø6.5')
for y in [-91.7,-74.3]:hole(y,-131,3.4,'Ø3.4')
for z in [-143.5,-108.5]:hole(-93,z,4.4,'Ø4.4')
a+=['<path d="M25,85h50 M25,83v4 M75,83v4" stroke="black" stroke-width="0.25" fill="none"/>','<text x="34" y="91" font-size="3">Calibration: exactly 50 mm</text>','<text x="10" y="98" font-size="2.6">Print 100%. Check scale and actual bearings before drilling.</text>','<text x="10" y="103" font-size="2.6">Hole coordinates are in the companion parts notes / CAD.</text>','</g></svg>']
(O/'Lovophone_Drive_End_Plate_Template.svg').write_text('\n'.join(a))
print('Parts list, stock notes and true-size end-plate template saved.')
